// Sample data: replace it with your own (a database, an API, another node).
const weeks = ['W1', 'W2', 'W3', 'W4', 'W5', 'W6', 'W7', 'W8'];
const mrr = [8200, 8650, 8400, 8900, 9100, 9350, 9100, 9840];
const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const thisWeek = [42, 55, 38, 61, 70, 33, 29];
const lastWeek = [36, 48, 41, 52, 58, 35, 24];
return [{ json: { weeks, mrr, days, thisWeek, lastWeek } }];

const { weeks, mrr, days, thisWeek, lastWeek } = $input.first().json;

const kpi = {
  type: 'line',
  data: { labels: weeks, datasets: [{ label: 'MRR', data: mrr }] },
  options: { plugins: { chartpng: { preset: 'kpi', previous: mrr.at(-2), prefix: '$' } } },
};
const comparison = {
  type: 'bar',
  data: {
    labels: days,
    datasets: [
      { label: 'This week', data: thisWeek },
      { label: 'Last week', data: lastWeek },
    ],
  },
  options: { plugins: { chartpng: { preset: 'comparison' } } },
};

const url = (chart, w, h) => 'https://chartpng.dev/chart?c=' + encodeURIComponent(JSON.stringify(chart)) + '&w=' + w + '&h=' + h + '&dpr=2';
const kpiUrl = url(kpi, 800, 400);
const comparisonUrl = url(comparison, 800, 450);

// Slack refuses an image block whose URL is longer than 3000 characters.
for (const imageUrl of [kpiUrl, comparisonUrl]) {
  if (imageUrl.length > 3000) throw new Error('A chart URL is longer than 3000 characters. Send fewer points.');
}

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: 'Weekly report' } },
  { type: 'image', image_url: kpiUrl, alt_text: 'MRR with its change and the last eight weeks' },
  { type: 'image', image_url: comparisonUrl, alt_text: 'This week against last week, by day' },
];
return [{ json: { kpiUrl, comparisonUrl, blocks } }];
